# Reproduce the coordinate transformation logic of win32.SetConsoleCursorPosition
# exactly as written in colorama/win32.py, using a fake COORD.

class FakeCOORD:
    def __init__(self, X=0, Y=0):
        self.X = X
        self.Y = Y
    def __repr__(self):
        return "COORD(X=%r, Y=%r)" % (self.X, self.Y)

captured = {}
def _SetConsoleCursorPosition(handle, coord):
    captured['coord'] = coord
    return True

def GetConsoleScreenBufferInfo(sid):
    class SR:
        Top = 0
        Left = 0
    class Info:
        srWindow = SR()
    return Info()

def SetConsoleCursorPosition(stream_id, position, adjust=True):
    position = FakeCOORD(*position)
    if position.Y <= 0 or position.X <= 0:
        return
    adjusted_position = FakeCOORD(position.Y - 1, position.X - 1)
    if adjust:
        sr = GetConsoleScreenBufferInfo(stream_id).srWindow
        adjusted_position.Y += sr.Top
        adjusted_position.X += sr.Left
    return _SetConsoleCursorPosition(stream_id, adjusted_position)

# ANSI: ESC [ row ; col H  -> params = (row, col)
